import {seed,money,names,terminal,sellable,available,totals,log,submit,transition,advance,assign,receive,proposeReplacement,respondReplacement,updateBranchLabels} from './domain.mjs';
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let s;try{s=JSON.parse(localStorage.getItem('ember-demo-v1'));if(s?.version!==1)s=seed()}catch{s=seed()}if(!s)s=seed();updateBranchLabels(s);s.products.forEach(p=>{p.name=p.name.replace('Ember cheeseburger','Signature cheeseburger')});s.orders.forEach(o=>o.lines.forEach(l=>{l.name=l.name.replace('Ember cheeseburger','Signature cheeseburger')}));
let route=location.hash.slice(1)||'menu',search='',category='All',orderFilter='active',role=(!location.hash||location.hash==='#menu')?'customer':'owner';
let atmospherePaused=false,logoClickTimer;
let dockPreference='true';
try{dockPreference=sessionStorage.getItem('paramount-nav-docked')??'true'}catch{}
const isDocked=()=>dockPreference==='true';
const paths={overview:['Overview','The whole service, in view.'],orders:['Orders','Every order. A clear next step.'],kitchen:['Kitchen & bar','Good timing is everything.'],availability:['Availability','Promise only what you can serve.'],dispatch:['Dispatch','From the pass to the doorstep.'],driver:['Driver workspace','Your next stop.'],supply:['Replenishment','Keep the next service ready.'],suppliers:['Supplier workspace','Know what’s needed. Confirm what’s coming.'],reports:['Performance','A closer look at online service.'],reconciliation:['Reconciliation','Close the loop, one order at a time.'],settings:['Service settings','Set the rhythm of your service.'],menu:['Restaurant home','Something good is on the way.'],order:['Order online','Find your next favourite.'],branches:['Our places','Four places. The same warm welcome.'],checkout:['Your tray','Make it a good meal.'],tracking:['Track your order','We’ll take it from here.'],services:['Gather with us','Make a little room for a good time.']};
const icons={overview:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',orders:'<path d="M6 3h12v18l-3-2-3 2-3-2-3 2zM9 7h6M9 11h6M9 15h3"/>',kitchen:'<path d="M4 14h16M5 14a7 7 0 0 1 14 0M3 18h18M12 7V4"/>',availability:'<path d="m3 7 9-4 9 4-9 4-9-4zm0 0v10l9 4 9-4V7M12 11v10"/>',dispatch:'<path d="M3 6h11v12H3zM14 10h4l3 4v4h-7M6 18a2 2 0 1 0 0 .1M17 18a2 2 0 1 0 0 .1"/>',driver:'<circle cx="12" cy="12" r="9"/><path d="m16 8-3 5-5 3 3-5z"/>',supply:'<path d="M4 7h16v14H4zM8 7V3h8v4M8 12h8M12 9v6"/>',reports:'<path d="M4 20V10M10 20V4M16 20v-8M22 20H2"/>',reconciliation:'<path d="M7 3h10v18H7zM10 7h4m-4 4h4m-4 4 2 2 3-3"/>',settings:'<circle cx="12" cy="12" r="3"/><path d="m9 3-1 3-3 1-2 5 2 5 3 1 1 3h6l1-3 3-1 2-5-2-5-3-1-1-3z"/>',menu:'<path d="M4 3v7a3 3 0 0 0 6 0V3M7 3v18M18 3v18M18 3c-4 2-4 9 0 9"/>',branches:'<path d="M20 10c0 6-8 12-8 12S4 16 4 10a8 8 0 1 1 16 0z"/><circle cx="12" cy="10" r="2"/>',checkout:'<path d="M3 18h18M5 16a7 7 0 0 1 14 0H5ZM12 8V5m-2 0h4M4 21h16"/>',tracking:'<circle cx="12" cy="12" r="9"/><path d="M12 6v6l4 2"/>',services:'<path d="M3 8h18M5 8v13m14-13v13M7 3v5m10-5v5M3 15h18"/>',suppliers:'<path d="M3 21V8l9-5 9 5v13H3M8 21v-8h8v8"/>'};
icons.order=icons.menu;
icons.menu='<path d="m3 10 9-7 9 7M5 9v12h14V9M9 21v-8h6v8"/>';
const icon=(id,cl='')=>`<svg class="icon ${cl}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[id]||icons.overview}</svg>`;
const productPhoto=p=>p.category==='Burgers & wraps'?'burger':p.category==='Something sweet'?'dessert':p.category==='Coffee'?'coffee':p.id==='p6'?'salad':p.id==='p8'?'fries':p.id==='p0'||p.id==='p7'?'chicken':'grill';
const branch=()=>s.branches.find(b=>b.id===s.branch),bn=id=>s.branches.find(b=>b.id===id)?.name||id;
const button=(text,action,cl='primary',more='')=>`<button class="btn ${cl}" data-action="${action}" ${more}>${text}</button>`;
const badge=(text,type='')=>`<span class="badge ${type}"><i></i>${esc(text)}</span>`;
const status=o=>badge(names[o.status],['delivered','collected','ready'].includes(o.status)?'green':['pending_acceptance','accepted'].includes(o.status)?'amber':['rejected','expired','cancelled'].includes(o.status)?'red':'');
const time=t=>{const m=12*60+30+t;return `${String(Math.floor(m/60)%24).padStart(2,'0')}:${String(m%60).padStart(2,'0')}`};
const filtered=()=>s.orders.filter(o=>s.branch==='all'||o.branch===s.branch);
const save=()=>localStorage.setItem('ember-demo-v1',JSON.stringify(s));
const notify=t=>{$('#toast').textContent=t;$('#toast').classList.add('show');setTimeout(()=>$('#toast').classList.remove('show'),3600)};
const go=r=>{if(r===route)render();else location.hash=r};
function nav(){const operational=[['SERVICE',['overview','orders','kitchen','availability']],['FULFILMENT',['dispatch','driver']],['BUSINESS',['supply','suppliers','reports','reconciliation','settings']],['GUEST EXPERIENCE',['menu','order','branches','services','tracking']]];const allow=role==='branch'?['orders','kitchen','availability','supply']:role==='dispatch'?['dispatch','driver']:role==='driver'?['driver']:role==='supplier'?['suppliers']:role==='customer'?['menu','order','branches','services','checkout','tracking']:null;return operational.map(([label,items])=>{items=items.filter(id=>!allow||allow.includes(id));return items.length?`<div class="navgroup"><span class="navlabel">${label}</span>${items.map(id=>`<a href="#${id}" aria-label="${id==='menu'?'Visit storefront':paths[id][0]}" title="${id==='menu'?'Visit storefront':paths[id][0]}" class="navitem ${route===id?'selected':''}">${icon(id)}<span>${id==='menu'?'Visit storefront':paths[id][0]}</span>${id==='orders'?'<small>'+s.orders.filter(o=>o.status==='pending_acceptance').length+'</small>':''}${id==='menu'?'<b>↗</b>':''}</a>`).join('')}</div>`:''}).join('')}
function render(){if(!paths[route])route='menu';document.body.classList.toggle('is-docked',isDocked());document.body.classList.toggle('is-storefront',route==='menu');document.body.classList.toggle('is-order-menu',route==='order');const customer=['menu','order','branches','checkout','tracking','services'].includes(route);$('#app').innerHTML=`<aside class="sidebar"><div class="brand-row"><button type="button" class="brand" aria-label="${isDocked()?'Expand navigation':'Dock navigation'}; double-click to return to top" aria-expanded="${!isDocked()}" aria-controls="workspace-navigation" title="Click to ${isDocked()?'expand':'dock'} the menu · double-click to return to top"><img class="brand-logo" src="/assets/paramount-logo.svg" alt="Paramount Signature — white chilli logo"><img class="brand-chilli" src="/assets/paramount-mark.svg" alt=""></button></div><nav id="workspace-navigation">${nav()}</nav><div class="sidebar-bottom"><div class="staff-avatar">PB</div><div>Demo workspace<small>Role preview · ${role}</small></div></div></aside><div class="page-shell"><header class="topbar"><div class="crumb"><button class="desktop-dock" data-action="dock" aria-label="${isDocked()?'Expand navigation':'Dock navigation'}" title="${isDocked()?'Expand navigation':'Dock navigation'}">☰</button><button class="mobilemenu" data-action="mobile" aria-label="Toggle navigation">☰</button>${route==='menu'?'<a href="#menu" class="hero-wordmark">PARAMOUNT <span>SIGNATURE</span></a>':''}</div>${route==='menu'?`<nav class="guest-nav" aria-label="Restaurant navigation"><button data-action="order-menu">Menus</button><a href="#branches">Our places</a><button data-action="gallery">The atmosphere</button><a class="visit-cta" href="#services">Plan a visit ↗</a></nav>`:''}<div class="topright"><span class="clock"><i></i>${time(s.time)} CAT</span><select id="role" aria-label="Preview role">${[['owner','Owner view'],['branch','Branch view'],['dispatch','Dispatch view'],['driver','Driver view'],['supplier','Supplier view'],['customer','Customer view']].map(([v,n])=>`<option value="${v}" ${role===v?'selected':''}>${n}</option>`).join('')}</select><a href="#checkout" class="basket-link" aria-label="Your serving tray, ${s.cart.reduce((n,l)=>n+l.quantity,0)} items">${icon('checkout')}<b>Your tray</b><span>${s.cart.reduce((n,l)=>n+l.quantity,0)}</span></a></div></header><main class="${customer?'customer':''} ${route==='menu'?'storefront-main':route==='order'?'catalogue-main':''}"><div class="pageheading"><div><div class="eyebrow">${customer?'THE PARAMOUNT EXPERIENCE':'SUNDAY, 25 OCTOBER · DEMO SERVICE'}</div><h1>${paths[route][1]}</h1><p>${subtitle()}</p></div>${!customer?route==='overview'?`<span class="branch-select all-branches">${icon('branches')} All four branches</span>`:`<label class="branch-select">${icon('branches')}<select id="branch" aria-label="Operating branch">${s.branches.map(b=>`<option value="${b.id}" ${s.branch===b.id?'selected':''}>${b.name} branch</option>`).join('')}</select></label>`:''}</div><div id="content" class="page-content">${views[route]()}</div><footer><span>Paramount Signature <span class="muted">/</span> Four branches. One service.</span><span>Demo menu, hours and street addresses</span></footer></main><div class="demo-bar"><span><i></i><strong>Interactive demo</strong><span class="demo-detail">Synthetic data · no real payments or messages</span></span><div><button data-action="scenarios">Scenarios <span>⌘</span></button><button data-action="advance">+5 min</button><button data-action="pause">${s.paused?'▷ Play':'Ⅱ Pause'}</button><button data-action="reset">Reset</button></div></div></div>`;bind();}
function subtitle(){return{overview:'A quieter view of a busy day. Here’s what needs your attention.',orders:'Accept, prepare and hand over — with nothing lost between.',kitchen:'Separate stations. One perfectly packed order.',availability:'Staff-confirmed online allowances, independent of your POS.',dispatch:'Keep pickups moving and customers in the loop.',driver:'A simple view for the person making the delivery.',supply:'Requests, confirmations and receiving across your branches.',suppliers:'An external supplier preview with synthetic purchase orders.',reports:'Measured from this demo’s orders, with clear definitions.',reconciliation:'Platform payments and manually recorded till references.',settings:'Illustrative operating policies for owner review.',order:'Choose a branch, browse what’s available, and build your tray.',menu:'Flame-grilled favourites, a well-stocked bar, and your favourite place.',branches:'Choose your local for delivery, collection, or a visit.',checkout:'One branch per order. Everything checked before confirmation.',tracking:'Your order, from the first flame to the final handover.',services:'Private gatherings, team lunches and evenings worth staying for.'}[route]}
function metrics(items){return `<div class="metrics">${items.map(([label,value,sub,cl])=>`<article class="metric"><span>${label}</span><strong>${value}</strong><small class="${cl||''}">${sub}</small></article>`).join('')}</div>`}
const panel=(title,sub,body,action='')=>`<section class="panel"><div class="panel-head"><div><h2>${title}</h2>${sub?`<p>${sub}</p>`:''}</div>${action}</div>${body}</section>`;
function orderTable(orders,limit=99){return `<div class="table-wrap"><table><thead><tr><th>Order / guest</th><th>Branch</th><th>Items</th><th>Status</th><th class="right">Total</th><th></th></tr></thead><tbody>${orders.slice(0,limit).map(o=>`<tr><td><button class="text-link" data-action="order" data-id="${o.id}">${o.id}</button><small>${esc(o.customer)}</small></td><td>${bn(o.branch)}<small>${o.mode==='delivery'?'Delivery':'Collection'}</small></td><td>${o.lines.reduce((n,l)=>n+l.quantity,0)} items<small>${time(o.created)}${o.status==='pending_acceptance'?' · '+Math.max(0,o.expires-s.time)+' min to accept':''}</small></td><td>${status(o)}</td><td class="right amount">${money(o.subtotal+o.fee)}</td><td><button class="row-arrow" data-action="order" data-id="${o.id}" aria-label="Open ${o.id}">↗</button></td></tr>`).join('')||'<tr><td colspan="6" class="empty">No orders here. A little breathing room.</td></tr>'}</tbody></table></div>`}
function overview(){const active=s.orders.filter(o=>!terminal.includes(o.status));const completed=s.orders.filter(o=>['delivered','collected'].includes(o.status));const revenue=s.orders.filter(o=>o.payment==='paid').reduce((n,o)=>n+o.subtotal-o.refund,0);return `<div class="overview-intro"><div><span class="live-label"><i></i> SERVICE AT A GLANCE</span><h2>A good day starts<br>with a clear picture.</h2><p>Four kitchens, one connected service.<br>Your next decisions are right here.</p><a href="#orders" class="btn primary">Open order board <span>↗</span></a></div><div class="intro-art"><img src="/assets/grill.jpg" alt="A freshly prepared grilled meal"/><span class="photo-note">MADE WITH FIRE.<br>SERVED WITH CARE.</span></div></div>${metrics([['Online merchandise sales',money(revenue),'Paid merchandise · all four branches'],['In service',active.length,'Orders awaiting completion'],['Completed',completed.length,'Delivered + collected'],['Needs acceptance',s.orders.filter(o=>o.status==='pending_acceptance').length,'Branch confirmation required','orange']])}<div class="section-title"><h2>Across the branches</h2><a href="#availability">Manage availability ↗</a></div><div class="branch-grid">${s.branches.map(b=>{let n=s.orders.filter(o=>o.branch===b.id&&!terminal.includes(o.status)).length;return `<a class="branch-card" href="#orders" data-branch="${b.id}"><div>${badge(b.mode==='busy'?'Busy kitchen':b.mode==='open'?'Taking orders':b.mode,b.mode==='open'?'green':'amber')}<span>↗</span></div><h3>${b.name}</h3><p>${b.area}</p><div class="branch-card-bottom"><span><b>${n}</b> active orders</span><span>${b.foodOpen?b.prep+'–'+(b.prep+10)+' min prep':'Bar service only'}</span></div></a>`}).join('')}</div><div class="dashboard-lower"><div>${panel('On the pass','Latest orders across the collective',orderTable(s.orders.filter(o=>!terminal.includes(o.status)),5),'<a href="#orders" class="text-link">View all ↗</a>')}</div><div>${panel('Worth your attention','Small actions. Better service.',`<div class="attention"><a href="#dispatch"><span class="attention-icon">${icon('dispatch')}</span><div><b>${s.orders.filter(o=>o.status==='ready'&&!o.driver&&o.mode==='delivery').length} ready orders need a driver</b><p>Keep the handover moving.</p></div><span>↗</span></a><a href="#availability"><span class="attention-icon">${icon('availability')}</span><div><b>CBD · quarter chicken sold out</b><p>Suggest another branch to guests.</p></div><span>↗</span></a><a href="#supply"><span class="attention-icon">${icon('supply')}</span><div><b>${s.purchaseOrders.filter(p=>p.status==='requested').length} replenishment requests</b><p>Review before the evening shift.</p></div><span>↗</span></a></div>`)}<div class="service-note"><span class="eyebrow">A LITTLE HEADS-UP</span><p>Hatfield’s kitchen is closed.<br>The bar is still taking orders.</p><a href="#settings">Review service hours ↗</a></div></div></div>`}
function orders(){const os=filtered().filter(o=>(orderFilter==='all'||orderFilter==='active'?!terminal.includes(o.status)||orderFilter==='all':o.status===orderFilter)&&(!search||JSON.stringify(o).toLowerCase().includes(search.toLowerCase())));return `<div class="toolbar"><div class="tabs">${[['active','In service'],['pending_acceptance','New'],['ready','Ready'],['all','All orders']].map(([v,n])=>`<button data-filter="${v}" class="${orderFilter===v?'active':''}">${n}</button>`).join('')}</div><input id="search" type="search" placeholder="Search order or guest…" value="${esc(search)}" aria-label="Search orders"></div>${panel('The order book',bn(s.branch)+' · '+os.length+' orders',orderTable(os))}`}
function kitchen(){let os=filtered().filter(o=>['accepted','preparing','ready'].includes(o.status));return `<div class="notice">${icon('kitchen')}<span>Kitchen and bar finish independently. An order reaches the pass when every station is ready.</span>${button('Refresh board','refresh','quiet')}</div><div class="kitchen-grid">${['accepted','preparing','ready'].map((st,i)=>`<section class="kanban-col"><div class="kanban-head"><h2>${['Queued','On the fire','At the pass'][i]}</h2><span>${os.filter(o=>o.status===st).length}</span></div>${os.filter(o=>o.status===st).map(o=>`<article class="ticket"><div class="ticket-head"><b>${o.id}</b><span>${Math.max(0,s.time-o.created)} min</span></div><p>${esc(o.customer)} · ${o.mode}</p><div class="ticket-lines">${o.lines.map(l=>`<div><b>${l.quantity}×</b><span>${esc(l.name)}<small>${l.station==='bar'?'BAR':'KITCHEN'}${l.modifier?' · '+esc(l.modifier):''}</small></span>${o.stations[l.station]?'<span class="done">✓</span>':''}</div>`).join('')}</div>${st==='accepted'?button('Start preparation','transition','primary wide',`data-id="${o.id}" data-next="start"`):st==='preparing'?`<div class="station-buttons">${[...new Set(o.lines.map(l=>l.station))].map(k=>button(o.stations[k]?'✓ '+k+' ready':'Finish '+k,'transition',o.stations[k]?'quiet':'secondary',`data-id="${o.id}" data-next="${k}" ${o.stations[k]?'disabled':''}`)).join('')}</div>`:button(o.mode==='collection'?'Confirm collection':'Open handover','transition', 'secondary wide',`data-id="${o.id}" data-next="${o.mode==='collection'?'collect':'detail'}"`)}</article>`).join('')||'<div class="column-empty">All clear for now.<br>New work will appear here.</div>'}</section>`).join('')}</div>`}
function availability(){const b=branch();return `<div class="service-controls"><div><h2>${b.name} service</h2><p>Adjust capacity before it affects the next order.</p></div><div class="segmented">${['open','busy','paused'].map(m=>`<button data-action="mode" data-mode="${m}" class="${b.mode===m?'active':''}">${{open:'Taking orders',busy:'Busy +10 min',paused:'Pause orders'}[m]}</button>`).join('')}</div></div><div class="notice">${icon('availability')}<span>Online allowance only. Walk-in sales need a staff adjustment. These figures are independent of the POS.</span>${button('Confirm all counts','confirm-stock','quiet')}</div>${panel('The availability sheet','Quantity shown after commitments, reservations and safety buffer.',`<div class="table-wrap"><table><thead><tr><th>Product</th><th>Station</th><th>Online remaining</th><th>Confirmation</th><th>Availability</th><th></th></tr></thead><tbody>${s.products.map(p=>{const a=s.offers[b.id+':'+p.id],n=sellable(a);return `<tr><td><b>${p.name}</b><small>${p.category}</small></td><td>${p.station}</td><td><b>${n}</b><small>${a.reserved} reserved · ${a.committed} committed</small></td><td>${s.time-a.updated} min ago</td><td>${badge(a.snoozed?'Snoozed':s.time-a.updated>=s.settings.freshness?'Confirm count':n===0?'Sold out':n<4?'Running low':'Available',n===0?'red':n<4||a.snoozed?'amber':'green')}</td><td class="right">${button('Adjust','stock','quiet',`data-id="${p.id}"`)}</td></tr>`}).join('')}</tbody></table></div>`)}`}
function dispatch(){const os=filtered().filter(o=>o.mode==='delivery'&&['ready','out_for_delivery','preparing','accepted'].includes(o.status));return `${metrics([['Awaiting a driver',os.filter(o=>!o.driver).length,'Accepted, preparing or ready'],['On the road',os.filter(o=>o.status==='out_for_delivery').length,'Deliveries in progress'],['Available drivers',s.drivers.filter(d=>d.online).length,'Across the collective'],['Delivery issue',s.orders.filter(o=>o.deliveryFailed).length,'Needs an operator decision']])}<div class="dispatch-layout">${panel('Pickup queue','Assignment considers driver availability and capacity.',os.map(o=>`<article class="dispatch-row"><div class="order-number">${icon('dispatch')}</div><div><button class="text-link" data-action="order" data-id="${o.id}">${o.id} · ${esc(o.customer)}</button><p>${bn(o.branch)} → ${esc(o.zone)} · ${money(o.subtotal+o.fee)}</p>${status(o)}${o.deliveryFailed?badge('Delivery failed','red'):''}</div><div>${o.driver?`<span class="assigned-name">${s.drivers.find(d=>d.id===o.driver)?.name}</span>`:button('Assign driver','assign','secondary',`data-id="${o.id}"`)}${o.status==='ready'&&o.driver?button('Confirm pickup','transition','primary',`data-id="${o.id}" data-next="pickup"`):''}</div></article>`).join('')||'<div class="empty">No deliveries awaiting action at this branch.</div>')}<div>${panel('On shift','Illustrative driver roster',s.drivers.map(d=>`<div class="driver-row"><span class="person-avatar">${d.name.split(' ').map(x=>x[0]).join('')}</span><div><b>${d.name}</b><small>${bn(d.branch)} · ${s.orders.filter(o=>o.driver===d.id&&!terminal.includes(o.status)).length}/${d.capacity} active jobs</small></div>${badge(d.online?'Online':'Offline',d.online?'green':'')}</div>`).join(''))}<div class="service-note"><span class="eyebrow">DISPATCH NOTE</span><p>A map can wait.<br>A ready meal shouldn’t.</p><small>Distances and ETAs in this demo are illustrative.</small></div></div></div>`}
function driver(){let d=s.drivers.find(d=>d.id===s.driver),os=s.orders.filter(o=>o.driver===d.id&&!terminal.includes(o.status));return `<div class="driver-intro"><div><span class="eyebrow">DRIVER PREVIEW</span><h2>Good afternoon, ${d.name.split(' ')[0]}.</h2><p>${os.length} active jobs · ${bn(d.branch)} base</p></div><select id="driver-select" aria-label="Preview driver">${s.drivers.map(d=>`<option value="${d.id}" ${d.id===s.driver?'selected':''}>${d.name}</option>`).join('')}</select></div><div class="driver-jobs">${os.map(o=>`<article class="panel driver-job"><div class="panel-head"><h2>${o.id}</h2>${status(o)}</div><div class="route-stop"><i>A</i><div><small>PICKUP</small><h3>Paramount Signature · ${bn(o.branch)}</h3><p>Confirm ${o.lines.reduce((n,l)=>n+l.quantity,0)} items and the order code at the pass.</p></div></div><div class="route-stop"><i>B</i><div><small>DELIVER TO</small><h3>${esc(o.customer)} · ${esc(o.zone)}</h3><p>${esc(o.address)}</p></div></div>${o.restricted?'<div class="notice amber">Restricted products · record verification before handover. Demo policy only.</div>':''}${o.cash?`<div class="cash-note">Collect ${money(o.subtotal+o.fee)} · demo cash order</div>`:''}<div class="button-row">${o.status==='ready'?button('Packages checked · pick up','transition','primary',`data-id="${o.id}" data-next="pickup"`):o.status==='out_for_delivery'?`${button('Complete delivery','delivery','primary',`data-id="${o.id}"`)}${button('Report a problem','failure','secondary',`data-id="${o.id}"`)}`:'<p>Wait for the branch to finish preparation.</p>'}</div>${o.deliveryFailed?'<div class="notice amber">Delivery issue recorded. Contact dispatch for resolution.</div>':''}</article>`).join('')||panel('A clear route','No active jobs assigned to this driver.',`<div class="empty">${icon('driver')}<p>Your next job will appear here after dispatch assigns it.</p><a href="#dispatch" class="btn secondary">Open dispatch</a></div>`)}</div>`}
function supply(supplier=false){let pos=s.purchaseOrders.filter(p=>supplier||p.branch===s.branch);return `<div class="toolbar"><div class="tabs"><span class="active">${supplier?'Incoming purchase orders':'Branch replenishment'}</span></div>${!supplier?button('+ New request','new-po'):''}</div>${panel(supplier?'Orders to fulfil':'The supply book',supplier?'Confirm quantities before the branch expects a delivery.':'An accepted receipt does not automatically increase online availability.',`<div class="table-wrap"><table><thead><tr><th>Reference / supplier</th><th>Branch / item</th><th>Ordered</th><th>Received</th><th>Status</th><th></th></tr></thead><tbody>${pos.map(p=>`<tr><td><b>${p.id}</b><small>${p.supplier}</small></td><td>${bn(p.branch)}<small>${p.item}</small></td><td>${p.ordered}<small>${p.confirmed} confirmed</small></td><td>${p.received}<small>${p.ordered-p.received} outstanding</small></td><td>${badge(p.status,p.status==='received'?'green':p.status==='partial'?'amber':'')}</td><td class="right">${p.status==='requested'?button(supplier?'Awaiting approval':'Approve request','approve-po','secondary',`data-id="${p.id}" ${supplier?'disabled':''}`):p.status==='approved'?button(supplier?'Confirm supply':'View supplier response','confirm-po','secondary',`data-id="${p.id}"`):p.status==='confirmed'||p.status==='partial'?button(supplier?'Review quantity':'Receive delivery',supplier?'confirm-po':'receive','secondary',`data-id="${p.id}"`):'<span class="muted">Complete</span>'}</td></tr>`).join('')}</tbody></table></div>`)}`}
function reports(){const os=filtered(),paid=os.filter(o=>o.payment==='paid'),completed=os.filter(o=>['delivered','collected'].includes(o.status)),decided=os.filter(o=>o.status!=='pending_acceptance'),accepted=decided.filter(o=>!['rejected','expired','cancelled'].includes(o.status));let max=Math.max(1,...s.products.map(p=>paid.reduce((n,o)=>n+o.lines.filter(l=>l.productId===p.id).reduce((n,l)=>n+l.quantity,0),0)));return `${metrics([['Net online merchandise',money(paid.reduce((n,o)=>n+o.subtotal-o.refund,0)),'Paid merchandise less refunds'],['Acceptance rate',decided.length?Math.round(100*accepted.length/decided.length)+'%':'N/A',accepted.length+' accepted / '+decided.length+' decisioned'],['Completed',completed.length,'Delivered and collected orders'],['On-time completion',completed.length?Math.round(100*completed.filter(o=>o.completed<=o.promised).length/completed.length)+'%':'N/A','Against original promised time']])}<div class="dashboard-lower">${panel('What guests are ordering','Paid online item quantities · this demo service',`<div class="bar-chart">${s.products.map(p=>({p,n:paid.reduce((n,o)=>n+o.lines.filter(l=>l.productId===p.id).reduce((n,l)=>n+l.quantity,0),0)})).filter(x=>x.n).sort((a,b)=>b.n-a.n).slice(0,8).map(({p,n})=>`<div><label>${p.name}</label><span><i style="width:${100*n/max}%"></i></span><b>${n}</b></div>`).join('')}</div>`)}${panel('Read the numbers','Scope matters.',`<div class="definition"><h3>Online orders only</h3><p>No walk-in or Touch Africa sales are included. Delivery charges and tips are excluded from merchandise sales.</p><h3>Single currency</h3><p>All amounts use USD demo pricing. Tax policy is illustrative and requires owner confirmation.</p><h3>Useful, not decorative</h3><p>Charts and totals are calculated from the same orders you see in the order book.</p></div>`)}</div>`}
function reconciliation(){return `<div class="notice">${icon('reconciliation')}<span>A manually entered POS receipt is a reference, not proof of an automatic match.</span></div>${panel('Close-out sheet','Record a reference, then explicitly review the amount.',`<div class="table-wrap"><table><thead><tr><th>Order / branch</th><th>Platform amount</th><th>Payment</th><th>POS reference</th><th>Review</th><th></th></tr></thead><tbody>${filtered().filter(o=>terminal.includes(o.status)).slice(0,20).map(o=>`<tr><td><b>${o.id}</b><small>${bn(o.branch)}</small></td><td>${money(o.subtotal+o.fee)}</td><td>${badge(o.payment,o.payment==='paid'?'green':'amber')}</td><td>${esc(o.receipt||'Not entered')}</td><td>${badge(o.reconciled?'Manually reviewed':o.receipt?'Reference entered':'Needs review',o.reconciled?'green':'amber')}</td><td>${button('Review','reconcile','quiet',`data-id="${o.id}"`)}</td></tr>`).join('')}</tbody></table></div>`)}`}
function settings(){const b=branch();return `<div class="settings-grid">${panel('Branch service','Changes also affect customer eligibility.',`<form id="settings-form" class="form-fields"><label>Branch<input value="${b.name}" disabled></label><label>Food service<select name="food"><option value="true" ${b.foodOpen?'selected':''}>Kitchen open</option><option value="false" ${!b.foodOpen?'selected':''}>Kitchen closed</option></select></label><label>Bar service<select name="bar"><option value="true" ${b.barOpen?'selected':''}>Bar open</option><option value="false" ${!b.barOpen?'selected':''}>Bar closed</option></select></label><label>Base preparation time (minutes)<input type="number" name="prep" min="5" max="120" value="${b.prep}" required></label><label>Acceptance window (minutes)<input name="acceptance" type="number" min="1" max="30" value="${s.settings.acceptance}" required></label><button class="btn primary">Save service settings</button></form>`)}${panel('Activity journal','Latest changes across the demo.',`<div class="journal">${s.audit.slice(0,15).map(a=>`<div><span>${time(a.at)}</span><div><p>${esc(a.text)}</p><small>${esc(a.actor)}</small></div></div>`).join('')}</div>`)}</div>`}
function menu(){let b=s.branches.find(b=>b.id===s.cartBranch);let ps=s.products.filter(p=>(category==='All'||p.category===category)&&(!search||(p.name+' '+p.description).toLowerCase().includes(search.toLowerCase())));return `<section class="signature-hero ${atmospherePaused?'motion-paused':''}" aria-label="Paramount Signature restaurant"><div class="hero-photo"><img src="/assets/grill.jpg" alt="Illustrative flame-grilled food" fetchpriority="high"><video class="hero-film" muted loop playsinline preload="none" poster="/assets/grill.jpg" aria-label="Illustrative footage of meat sizzling on a grill"><source data-src="/assets/paramount-grill.mp4" type="video/mp4"></video></div><div class="hero-shade"></div><div class="ember-atmosphere" aria-hidden="true">${Array.from({length:7},(_,i)=>`<i style="--n:${i}"></i>`).join('')}</div><div class="hero-copy"><div class="hero-kicker"><span></span> FIRE. FLAVOUR. GOOD COMPANY.</div><h1><span>A little fire.</span><em>A lot of flavour.</em></h1><p>Flame-grilled favourites. A cold drink.<br>Find your spot. Stay a little longer.</p><div class="hero-actions">${button('Explore the menu <span>↗</span>','order-menu','hero-primary')}<a href="#branches" class="hero-places">Find your place <span>↗</span></a></div></div><div class="flavour-seal" aria-hidden="true"><svg viewBox="0 0 160 160"><defs><path id="seal-circle" d="M80,80 m-59,0 a59,59 0 1,1 118,0 a59,59 0 1,1 -118,0"/></defs><text><textPath href="#seal-circle">FIRE UP YOUR FAVOURITES · PARAMOUNT SIGNATURE · </textPath></text></svg><img src="/assets/paramount-mark.svg" alt=""></div><div class="hero-bottom"><span>GRILL & BAR <i>✦</i> HARARE</span><button data-action="explore" class="scroll-menu"><span>Discover what’s cooking</span><b>↓</b></button><button class="motion-control" data-action="hero-motion" aria-pressed="false">Ⅱ Pause atmosphere</button></div></section><section class="visit-story" aria-labelledby="visit-title"><div class="visit-photo reveal"><img src="/assets/atmosphere.jpg" alt="Illustrative restaurant atmosphere with timber, greenery and warm lighting" loading="lazy"><span>GOOD FOOD. YOUR KIND OF COMPANY.</span></div><div class="visit-copy reveal"><span class="eyebrow">THE PARAMOUNT WAY</span><h2 id="visit-title">Pull up a chair.<br><em>Stay for the company.</em></h2><p>A meal with the family. A catch-up over drinks. An evening that takes its own time. Choose your Paramount spot, or let us bring your favourites to you.</p><div class="visit-details"><div>${icon('branches')}<span><b>Find your local</b><small>Explore four branches in this demonstration.</small></span></div><div>${icon('kitchen')}<span><b>Food, drinks & good company</b><small>Branch availability shown before you order.</small></span></div></div><div class="button-row"><a class="btn visit-gold" href="#branches">Choose your branch ↗</a><a class="btn visit-outline" href="#services">Plan a gathering ↗</a></div><p class="visit-disclaimer">Hours, street addresses and imagery are illustrative until business details are confirmed.</p></div></section><section class="menu-collections" id="menu-collections" aria-labelledby="collections-title"><div class="collections-heading"><span class="eyebrow">THERE’S SOMETHING FOR YOUR MOOD</span><h2 id="collections-title">CHOOSE YOUR<br><em>KIND OF HEAT.</em></h2></div><div class="collection-grid">${[['Food menu','From the grill','grill','Flame-grilled favourites'],['Drinks menu','Soft drinks','cocktails','Something refreshing'],['Small plates','Small plates','fries','A little something to share'],['Bar selection','Beer & cider','cocktails','A well-earned cold one']].map(([title,c,img,caption],i)=>`<button class="collection-panel" data-action="collection" data-category="${c}" style="--delay:${i*80}ms"><img src="/assets/${img}.jpg" alt="Illustrative ${title.toLowerCase()} photography" loading="lazy"><span class="collection-number">0${i+1}</span><div><small>${caption}</small><h3>${title}</h3><span class="collection-link">OPEN MENU <b>↗</b></span></div></button>`).join('')}</div></section><section class="atmosphere-gallery" id="atmosphere-gallery"><div class="gallery-heading reveal"><span class="eyebrow">SETTLE INTO THE MOMENT</span><h2>A taste of <em>the atmosphere.</em></h2><p>Warm light. A table of favourites. Time well spent.</p></div><div class="gallery-tiles"><figure class="reveal"><img src="/assets/atmosphere.jpg" alt="Illustrative timber and greenery restaurant interior" loading="lazy"><figcaption>A place to linger</figcaption></figure><figure class="reveal"><img src="/assets/cocktails.jpg" alt="Illustrative drinks and bar atmosphere" loading="lazy"><figcaption>Raise a glass</figcaption></figure><figure class="reveal"><img src="/assets/grill.jpg" alt="Illustrative flame-grilled meal" loading="lazy"><figcaption>From the fire</figcaption></figure></div><a class="btn visit-outline" href="#services">Make an occasion of it ↗</a></section>`}

function catalogue(){const b=s.branches.find(b=>b.id===s.cartBranch);const ps=s.products.filter(p=>(category==='All'||p.category===category)&&(!search||(p.name+' '+p.description).toLowerCase().includes(search.toLowerCase())));return `<a href="#menu" class="catalogue-back">← Back to Paramount Signature</a><section class="restaurant-menu" id="restaurant-menu" aria-label="Order from the menu"><div class="menu-intro"><div><span class="eyebrow">YOUR NEXT GOOD MEAL</span><h2>What are you<br><em>in the mood for?</em></h2></div><p>Choose your branch. Find your favourite.<br>We’ll take care of the fire.</p></div><div class="store-controls"><label>${icon('branches')}<select id="shop-branch" aria-label="Order from branch">${s.branches.map(x=>`<option value="${x.id}" ${b.id===x.id?'selected':''}>${x.name}</option>`).join('')}</select></label><span>${badge(b.mode==='open'?'Taking orders':b.mode,b.mode==='open'?'green':'amber')}<small>${b.prep+(b.mode==='busy'?10:0)}–${b.prep+(b.mode==='busy'?20:10)} min preparation</small></span><label class="search-box"><input id="menu-search" type="search" placeholder="Find your favourite…" value="${esc(search)}" aria-label="Search menu"></label></div><div class="category-tabs">${['All',...new Set(s.products.map(p=>p.category))].map(c=>`<button class="${category===c?'active':''}" data-category="${c}">${c}</button>`).join('')}</div><div class="menu-heading"><h2>${category==='All'?'The menu':category}</h2><span>Made fresh. Worth the wait.</span></div><div class="product-grid">${ps.map((p,i)=>{const a=s.offers[b.id+':'+p.id],av=available(s,b.id,p);return `<article class="product-card ${!av?'unavailable':''}"><div class="product-image ${p.station==='bar'?'drink-image':''}">${p.station==='kitchen'||p.category==='Coffee'?`<img src="/assets/${productPhoto(p)}.jpg" alt="Illustrative ${p.category.toLowerCase()} photograph" loading="lazy" style="object-position:${20+(i%4)*20}% ${30+(i%3)*20}%">`:`<div class="drink-illustration ${p.restricted?'bottle':'glass'}"><i></i></div>`}<span>${p.restricted?'RESTRICTED PRODUCT':p.category.toUpperCase()}</span></div><div class="product-info"><h3>${p.name}</h3><p>${p.description}</p><div><b>${money(p.price)}</b>${av?button('+','product','round',`data-id="${p.id}" aria-label="Add ${p.name}"`):`<button class="sold-button" data-action="alternatives" data-id="${p.id}">Find at another branch ↗</button>`}</div>${!av?'<small class="stock-label">Unavailable at this branch</small>':sellable(a)<4?`<small class="stock-label">Only ${sellable(a)} online portions left</small>`:''}</div></article>`}).join('')||'<div class="empty">No menu items match that search.</div>'}</div></section>`}
function branches(){return `<div class="places-grid">${s.branches.map((b,i)=>`<article class="place-card"><div class="place-art p${i}"><span>0${i+1}</span><div class="building"><i></i><b>PARAMOUNT SIGNATURE</b></div></div><div class="place-info"><div>${badge(b.mode,b.mode==='open'?'green':'amber')}<span>${b.prep}–${b.prep+10} min</span></div><h2>${b.name}</h2><p>${b.area}</p><small>${b.address}</small><div class="place-hours"><span>Kitchen <b>${b.foodOpen?'Open':'Closed'}</b></span><span>Bar <b>${b.barOpen?'Open':'Closed'}</b></span></div>${button('Order from '+b.name,'choose-branch','primary wide',`data-id="${b.id}"`)}</div></article>`).join('')}</div>`}
function checkout(){if(!s.cart.length)return panel('A little room for something good.','Your tray is empty.',`<div class="empty">${icon('checkout')}<p>Choose a meal or a drink from your local branch.</p><a href="#order" class="btn primary">Explore the menu ↗</a></div>`);const t=totals(s.cart,s.fulfilment);return `<div class="checkout-layout">${panel('Your order',bn(s.cartBranch)+' branch · one branch per tray',`<div class="basket-lines">${s.cart.map((l,i)=>`<div><div><h3>${esc(l.name)}</h3><p>${esc(l.modifier||'Standard')}${l.extra?' · extra cheese':''}</p><div class="quantity"><button data-action="qty" data-index="${i}" data-delta="-1" aria-label="Remove one ${esc(l.name)}">−</button><span>${l.quantity}</span><button data-action="qty" data-index="${i}" data-delta="1" aria-label="Add one ${esc(l.name)}">+</button></div></div><b>${money(l.price*l.quantity)}</b></div>`).join('')}</div><a href="#order" class="text-link">← Add something else</a>`)}${panel('The final details','No real payment will be taken.',`<form id="checkout-form" class="form-fields"><div class="segmented"><button type="button" data-action="fulfilment" data-mode="delivery" class="${s.fulfilment==='delivery'?'active':''}">Delivery</button><button type="button" data-action="fulfilment" data-mode="collection" class="${s.fulfilment==='collection'?'active':''}">Collection</button></div><label>Your name<input name="customer" placeholder="e.g. Tariro M." required maxlength="60"></label>${s.fulfilment==='delivery'?`<label>Demo delivery area<select name="zone"><option>Chitungwiza</option><option>CBD</option><option>Borrowdale</option><option>Hatfield</option><option value="outside">Outside service area</option></select></label><label>Address and landmark<textarea name="address" required placeholder="Use a fictional address for this demo"></textarea></label>`:''}<label>Payment simulation<select name="payment"><option value="card">Successful demo payment</option><option value="cash">Cash on delivery / collection</option><option value="failed">Test declined payment</option></select></label>${s.cart.some(l=>s.products.find(p=>p.id===l.productId).restricted)?'<label class="checkbox"><input type="checkbox" name="age" required> I confirm eligibility under the illustrative restricted-product policy. Verification is required at handover.</label>':''}<div class="totals"><div><span>Items</span><span>${money(t.subtotal)}</span></div><div><span>${s.fulfilment==='delivery'?'Delivery · fixed demo zone fee':'Collection'}</span><span>${money(t.fee)}</span></div><div class="total"><b>Total · USD</b><b>${money(t.total)}</b></div></div><p class="fineprint">Demo prices are final shown prices. Production tax treatment and restricted-product policies need owner approval.</p><button class="btn primary wide">Place demo order · ${money(t.total)} →</button></form>`)}</div>`}
function tracking(){const os=s.orders.filter(o=>o.id===s.activeOrder);const o=os[0];if(!o)return panel('Nothing on the way yet.','Place an order to follow its progress.',`<div class="empty"><a class="btn primary" href="#order">Order something good ↗</a></div>`);const steps=['pending_acceptance','accepted','preparing','ready','out_for_delivery','delivered'];if(o.mode==='collection'){steps.splice(4,2,'collected')}let idx=steps.indexOf(o.status);return `<div class="tracking-layout">${panel('Your meal is '+(o.status==='pending_acceptance'?'awaiting confirmation.':o.status==='delivered'?'at your door.':o.status==='collected'?'in your hands.':'making progress.'),o.id+' · '+bn(o.branch)+' branch',`<div class="tracking-progress">${steps.map((st,i)=>`<div class="${i<=idx?'reached':''}"><i>${i<idx?'✓':i+1}</i><div><h3>${names[st]}</h3><p>${i===idx?'You are here':i<idx?'Completed':'Coming up'}</p></div></div>`).join('')}</div>${terminal.includes(o.status)&&!['delivered','collected'].includes(o.status)?`<div class="notice amber">${names[o.status]} · ${o.payment==='refund_pending'?'Refund requires resolution in the demo.':'No further fulfilment.'}</div>`:''}${!terminal.includes(o.status)?`<div class="notice eta-note">${icon('tracking')}<span>Estimated ${o.mode==='delivery'?'arrival':'collection'}: ${time(o.promised-5)}–${time(o.promised+5)} CAT<br><small>Illustrative estimate · branch and delivery conditions may change</small></span></div>`:''}${o.deliveryFailed?'<div class="notice amber">There’s a delivery issue. Dispatch is reviewing the next step.</div>':''}`)}<div>${panel('Order details',esc(o.customer),`<div class="definition">${o.lines.map(l=>`<p>${l.quantity} × ${esc(l.name)} <b>${money(l.quantity*l.price)}</b></p>`).join('')}<hr><p>Total <b>${money(o.subtotal+o.fee)}</b></p><p>Payment <b>${o.payment.replaceAll('_',' ')}</b></p><p>${o.mode==='delivery'?'Delivery to '+esc(o.zone):'Collect from '+bn(o.branch)}</p>${o.proposal?`<div class="notice amber">The branch suggests ${esc(o.proposal.name)} instead of ${esc(o.lines[0].name)}. Revised total: ${money(o.subtotal+o.fee+(o.proposal.price-o.lines[0].price)*o.lines[0].quantity)}. Approving also simulates the payment adjustment.</div><div class="button-row">${button('Approve replacement','respond-replacement','primary',`data-id="${o.id}" data-approve="true"`)}${button('Decline','respond-replacement','secondary',`data-id="${o.id}" data-approve="false"`)}</div>`:''}${button('Ask for help','help','secondary wide',`data-id="${o.id}"`)}${o.status==='pending_acceptance'?button('Cancel order','transition','quiet wide',`data-id="${o.id}" data-next="cancel"`):''}</div>`)}${panel('Latest updates','Shared with the branch workspace.',`<div class="journal">${o.events.slice().reverse().map(e=>`<div><span>${time(e.at)}</span><p>${esc(e.text)}</p></div>`).join('')}</div>`)}</div></div>`}
function services(){return `<section class="gather-hero"><img class="gather-photo" src="/assets/atmosphere.jpg" alt="Illustrative restaurant dining room with timber tables, greenery and warm lighting" fetchpriority="high"><span class="eyebrow">A TABLE FOR YOUR OCCASION</span><h2>Some moments<br>deserve a gathering.</h2><p>Team lunches, birthdays, private dinners.<br>Tell us what you have in mind.</p></section><div class="settings-grid">${panel('Make an enquiry','An enquiry is not a confirmed booking.',`<form id="enquiry-form" class="form-fields"><label>Your name<input name="name" required maxlength="60"></label><label>Occasion<select name="occasion"><option>Private dinner</option><option>Team lunch</option><option>Birthday gathering</option><option>Other occasion</option></select></label><label>Preferred branch<select name="branch">${s.branches.map(b=>`<option>${b.name}</option>`).join('')}</select></label><div class="form-two"><label>Preferred date<input type="date" name="date" required min="2026-10-25"></label><label>Guests<input type="number" name="guests" min="2" max="100" value="12" required></label></div><label>A little more about it<textarea name="notes" maxlength="500"></textarea></label><button class="btn primary">Save demo enquiry ↗</button></form>`)}${panel('Your occasions','Saved only in this browser demonstration.',s.enquiries.length?`<div class="definition">${s.enquiries.map(e=>`<article class="enquiry"><span class="eyebrow">${esc(e.date)} · ${esc(e.branch)}</span><h3>${esc(e.occasion)}</h3><p>${esc(e.name)} · ${e.guests} guests</p>${badge('Enquiry received','green')}</article>`).join('')}</div>`:'<div class="empty">Your enquiry will appear here.<br>No real message will be sent.</div>')}</div>`}
const views={overview,orders,kitchen,availability,dispatch,driver,supply:()=>supply(false),suppliers:()=>supply(true),reports,reconciliation,settings,menu,order:catalogue,branches,checkout,tracking,services};
function modal(title,body,wide=false){$('#overlay').innerHTML=`<div class="modal-backdrop"><section class="modal ${wide?'modal-wide':''}" role="dialog" aria-modal="true" aria-labelledby="modal-title" tabindex="-1"><div class="modal-header"><h2 id="modal-title">${title}</h2><button class="close" data-close aria-label="Close dialog">×</button></div><div class="modal-body">${body}</div></section></div>`;$('#overlay [data-close]').onclick=close;$('#overlay .modal-backdrop').onclick=e=>{if(e.target===e.currentTarget)close()};$('#overlay .modal').focus();$('#overlay').onkeydown=e=>{if(e.key==='Escape')close();if(e.key==='Tab'){let a=[...$('#overlay').querySelectorAll('button,input,select,textarea,a[href]')].filter(x=>!x.disabled);if(e.shiftKey&&document.activeElement===a[0]){e.preventDefault();a.at(-1).focus()}else if(!e.shiftKey&&document.activeElement===a.at(-1)){e.preventDefault();a[0].focus()}}};}
function close(){$('#overlay').innerHTML=''}
function orderDetail(id){const o=s.orders.find(x=>x.id===id);modal(o.id+' · '+esc(o.customer),`<div class="detail-summary">${status(o)}<span>${bn(o.branch)} · ${o.mode}</span></div><div class="detail-lines">${o.lines.map(l=>`<p><span>${l.quantity} × ${esc(l.name)}</span><b>${money(l.price*l.quantity)}</b></p>`).join('')}<p><span>Delivery</span><b>${money(o.fee)}</b></p><p class="total"><b>Total · USD</b><b>${money(o.subtotal+o.fee)}</b></p></div><div class="notice">${o.payment==='paid'?'Demo payment successful':esc(o.payment.replaceAll('_',' '))} · ${o.mode==='delivery'?esc(o.zone):'Collection at branch'}</div><div class="button-row">${o.status==='pending_acceptance'?button('Accept order','transition','primary',`data-id="${id}" data-next="accept"`)+button('Reject','transition','secondary',`data-id="${id}" data-next="reject"`):o.status==='accepted'?button('Start preparation','transition','primary',`data-id="${id}" data-next="start"`):o.status==='preparing'?'<a href="#kitchen" class="btn primary" data-close-link>Open kitchen board →</a>':o.status==='ready'?(o.mode==='collection'?button('Confirm collection','transition','primary',`data-id="${id}" data-next="collect"`):o.driver?button('Confirm pickup','transition','primary',`data-id="${id}" data-next="pickup"`):button('Assign driver','assign','primary',`data-id="${id}"`)):o.status==='out_for_delivery'?button('Complete delivery','delivery','primary',`data-id="${id}"`):''}${o.status==='accepted'?button('Propose replacement','substitute','secondary',`data-id="${id}"`):''}${o.payment==='refund_pending'?button('Resolve demo refund','refund','secondary',`data-id="${id}"`):''}${button('Customer tracking','track-order','quiet',`data-id="${id}"`)}</div><div class="journal">${o.events.slice().reverse().map(e=>`<div><span>${time(e.at)}</span><p>${esc(e.text)}</p></div>`).join('')}</div>`);bindOverlay();}
function bindOverlay(){$('#overlay').querySelectorAll('[data-action]').forEach(el=>el.onclick=()=>act(el));$('#overlay').querySelectorAll('[data-close-link]').forEach(el=>el.onclick=close)}
function syncCustomerChrome(){
 const quantity=s.cart.reduce((n,l)=>n+l.quantity,0);
 const tray=$('.basket-link');if(tray){tray.setAttribute('aria-label',`Your serving tray, ${quantity} items`);tray.querySelector('span').textContent=quantity;}
 const clock=$('.clock');if(clock)clock.innerHTML=`<i></i>${time(s.time)} CAT`;
 const pause=$('[data-action="pause"]');if(pause)pause.textContent=s.paused?'▷ Play':'Ⅱ Pause';
 const pending=$('.navitem[href="#orders"] small');if(pending)pending.textContent=s.orders.filter(o=>o.status==='pending_acceptance').length;

}
function refreshCatalogue(){if(route!=='order')return;const template=document.createElement('template');template.innerHTML=catalogue();for(const sel of ['.product-grid','.menu-heading']){const current=$(sel),next=template.content.querySelector(sel);if(current&&next)current.replaceWith(next);}document.querySelectorAll('.product-grid [data-action]').forEach(el=>el.onclick=()=>act(el));}
function refreshCustomer(){syncCustomerChrome();if(route==='order')refreshCatalogue();}
function update(fn,msg){try{fn();save();close();if(['menu','order'].includes(route))refreshCustomer();else render();if(msg)notify(msg)}catch(e){notify(e.message)}}
function changeBranch(id){if(s.cart.length&&id!==s.cartBranch){modal('Switch your branch?',`<p>Your tray belongs to ${bn(s.cartBranch)}. Switching clears it so prices and availability can be checked at ${bn(id)}.</p><div class="button-row">${button('Clear tray & switch','switch-confirm','primary',`data-id="${id}"`)}${button('Keep current branch','close','secondary')}</div>`);bindOverlay();return;}s.cartBranch=id;save();render()}
function toggleNavigation(){
 if(window.matchMedia('(max-width:760px)').matches){$('.sidebar')?.classList.toggle('mobile-open');return;}
 dockPreference=String(!isDocked());try{sessionStorage.setItem('paramount-nav-docked',dockPreference)}catch{}document.body.classList.toggle('is-docked',isDocked());
 document.querySelectorAll('[data-action="dock"]').forEach(b=>{b.setAttribute('aria-label',isDocked()?'Expand navigation':'Dock navigation');b.setAttribute('title',isDocked()?'Expand navigation':'Dock navigation');b.setAttribute('aria-expanded',String(!isDocked()))});
 const logo=$('.brand');if(logo){logo.setAttribute('aria-expanded',String(!isDocked()));logo.setAttribute('aria-label',`${isDocked()?'Expand navigation':'Dock navigation'}; double-click to return to top`);logo.title=`Click to ${isDocked()?'expand':'dock'} the menu · double-click to return to top`;}
}
function act(el){const a=el.dataset.action,id=el.dataset.id;try{
if(a==='dock'){toggleNavigation();return}
if(a==='gallery'){document.getElementById('atmosphere-gallery').scrollIntoView({behavior:window.matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});return}
if(a==='order-menu'){category='All';search='';go('order');return}
if(a==='collection'){category=el.dataset.category;search='';go('order');return}
if(a==='explore'){document.getElementById('menu-collections').scrollIntoView({behavior:window.matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'start'});return}
if(a==='hero-motion'){let hero=$('.signature-hero');let paused=hero.classList.toggle('motion-paused');atmospherePaused=paused;const film=hero.querySelector('video');if(film){if(paused)film.pause();else{const src=film.querySelector('source');if(!src.src){src.src=src.dataset.src;film.load()}film.play().then(()=>film.classList.add('playing')).catch(()=>{})}}el.textContent=paused?'▷ Play atmosphere':'Ⅱ Pause atmosphere';el.setAttribute('aria-pressed',String(paused));return}
if(a==='close'){close();return}if(a==='mobile'){$('.sidebar').classList.toggle('mobile-open');return}if(a==='refresh'){render();notify('Board refreshed from shared demo state.');return}
if(a==='order'){orderDetail(id);return}if(a==='transition'){if(el.dataset.next==='collect'&&s.orders.find(o=>o.id===id)?.restricted){modal('Collection verification',`<form id="collect-form" class="form-fields"><label class="checkbox"><input type="checkbox" required> Restricted-product verification passed under the demo policy</label><button class="btn primary">Confirm verified collection</button></form>`);$('#collect-form').onsubmit=e=>{e.preventDefault();update(()=>transition(s,id,'collect'),'Verified collection recorded.')};return}if(el.dataset.next==='detail'){orderDetail(id);return}update(()=>transition(s,id,el.dataset.next),'Order updated across the workspace.');return}
if(a==='substitute'){const o=s.orders.find(o=>o.id===id);modal('Propose a replacement',`<p>Replace ${esc(o.lines[0].name)}. The customer must approve the new item and total before preparation.</p><form id="replacement-form" class="form-fields"><label>Available replacement<select name="product">${s.products.filter(p=>p.station===o.lines[0].station&&p.id!==o.lines[0].productId&&available(s,o.branch,p)).map(p=>`<option value="${p.id}">${p.name} · ${money(p.price)}</option>`).join('')}</select></label><button class="btn primary">Send demo proposal</button></form>`);$('#replacement-form').onsubmit=e=>{e.preventDefault();update(()=>proposeReplacement(s,id,new FormData(e.target).get('product')),'Proposal visible in customer tracking.')};return}
if(a==='respond-replacement'){update(()=>respondReplacement(s,id,el.dataset.approve==='true'),'Customer response recorded.');return}
if(a==='refund'){update(()=>{const o=s.orders.find(o=>o.id===id);if(o.payment!=='refund_pending')throw Error('No pending refund.');o.payment='refunded';o.refund=o.subtotal;o.events.push({at:s.time,text:'Demo refund resolved'});log(s,id+' refund resolved · simulation only')},'Demo refund recorded. No real payment action occurred.');return}
if(a==='track-order'){s.activeOrder=id;save();close();go('tracking');return}
if(a==='advance'){update(()=>advance(s),'Demo clock advanced. Expired reservations released.');return}if(a==='pause'){s.paused=!s.paused;save();if(['menu','order'].includes(route))syncCustomerChrome();else render();return}
if(a==='reset'){modal('Start a fresh service?',`<p>This resets all orders, stock changes and enquiries made in this demo browser.</p>${button('Reset demonstration','reset-confirm')}`);bindOverlay();return}if(a==='reset-confirm'){s=seed();save();close();render();notify('A fresh demo service is ready.');return}
if(a==='mode'){update(()=>{branch().mode=el.dataset.mode;log(s,bn(s.branch)+' set to '+el.dataset.mode)},'Service mode updated.');return}
if(a==='confirm-stock'){update(()=>{s.products.forEach(p=>s.offers[s.branch+':'+p.id].updated=s.time);log(s,bn(s.branch)+' stock confirmations refreshed')},'Counts confirmed by demo operator.');return}
if(a==='stock'){let p=s.products.find(p=>p.id===id),v=s.offers[s.branch+':'+id];modal('Adjust '+p.name,`<p>${bn(s.branch)} · online allowance, separate from physical stock.</p><form id="stock-form" class="form-fields"><label>New sellable allowance<input type="number" name="qty" value="${sellable(v)}" min="0" max="500" required></label><label>Availability<select name="snooze"><option value="false" ${!v.snoozed?'selected':''}>Available within count</option><option value="true" ${v.snoozed?'selected':''}>Snooze ordering</option></select></label><label>Reason<select name="reason"><option>Shift count confirmed</option><option>Stock diverted to walk-ins</option><option>Supplier delivery allocated online</option><option>Kitchen unable to prepare</option></select></label><button class="btn primary">Save availability</button></form>`);$('#stock-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);update(()=>{v.allocation=+f.get('qty')+v.consumed+v.committed+v.reserved+v.buffer;v.snoozed=f.get('snooze')==='true';v.updated=s.time;log(s,p.name+' allowance adjusted: '+f.get('reason'))},'Availability updated on the customer menu.')};return}
if(a==='product'){const p=s.products.find(p=>p.id===id);modal(p.name,`<p>${p.description}</p><form id="product-form" class="form-fields">${p.modifiers.length?`<label>Choose your flavour<select name="modifier" required><option value="">Select a flavour</option>${p.modifiers.map(m=>`<option>${m}</option>`).join('')}</select></label>`:''}${p.extra?`<label class="checkbox"><input type="checkbox" name="extra"> Add cheese · ${money(p.extra)}</label>`:''}<label>Quantity<input type="number" name="quantity" min="1" max="${sellable(s.offers[s.cartBranch+':'+id])}" value="1" required></label><button class="btn primary wide">Add to tray · from ${money(p.price)}</button></form>`);$('#product-form').onsubmit=e=>{e.preventDefault();let f=new FormData(e.target),q=+f.get('quantity'),extra=f.get('extra')==='on',modifier=f.get('modifier')||'',price=p.price+(extra?p.extra:0);update(()=>{if(!available(s,s.cartBranch,p)||q+s.cart.filter(l=>l.productId===id).reduce((n,l)=>n+l.quantity,0)>sellable(s.offers[s.cartBranch+':'+id]))throw Error('Not enough online allowance for this quantity.');let l=s.cart.find(l=>l.productId===id&&l.modifier===modifier&&l.extra===extra);if(l)l.quantity+=q;else s.cart.push({productId:id,name:p.name,price,quantity:q,station:p.station,modifier,extra})},'Added to your tray.')};return}
if(a==='alternatives'){const p=s.products.find(p=>p.id===id);modal('Find '+p.name,`<p>Availability is branch-specific. Switching branches clears an existing tray.</p><div class="alternative-list">${s.branches.map(b=>`<div><b>${b.name}</b>${available(s,b.id,p)?button('Choose branch','choose-branch','secondary',`data-id="${b.id}"`):badge('Unavailable','red')}</div>`).join('')}</div>`);bindOverlay();return}
if(a==='choose-branch'){close();changeBranch(id);if(!s.cart.length)go('order');return}if(a==='switch-confirm'){s.cart=[];s.cartBranch=id;save();close();go('order');render();return}
if(a==='qty'){let l=s.cart[+el.dataset.index];if(+el.dataset.delta>0&&s.cart.filter(x=>x.productId===l.productId).reduce((n,x)=>n+x.quantity,0)>=sellable(s.offers[s.cartBranch+':'+l.productId]))throw Error('This is the last available online portion.');l.quantity+=+el.dataset.delta;s.cart=s.cart.filter(l=>l.quantity>0);save();render();return}
if(a==='fulfilment'){s.fulfilment=el.dataset.mode;save();render();return}
if(a==='assign'){modal('Assign driver · '+id,`<p>Online drivers with capacity. Pickup estimates are illustrative.</p><div class="alternative-list">${s.drivers.map(d=>{let n=s.orders.filter(o=>o.driver===d.id&&!terminal.includes(o.status)).length;return `<div><span><b>${d.name}</b><small>${bn(d.branch)} · ${n}/${d.capacity} jobs</small></span>${button(d.online&&n<d.capacity?'Assign':'Unavailable','assign-confirm','secondary',`data-id="${id}" data-driver="${d.id}" ${!d.online||n>=d.capacity?'disabled':''}`)}</div>`}).join('')}</div>`);bindOverlay();return}if(a==='assign-confirm'){update(()=>assign(s,id,el.dataset.driver),'Driver assigned.');return}
if(a==='delivery'){let o=s.orders.find(x=>x.id===id);modal('Complete delivery · '+id,`<form id="delivery-form" class="form-fields"><label class="checkbox"><input type="checkbox" required> Package and recipient confirmed</label>${o.restricted?'<label class="checkbox"><input type="checkbox" required> Restricted-product verification passed under the demo policy</label>':''}${o.cash?`<label class="checkbox"><input type="checkbox" required> Demo cash collected · ${money(o.subtotal+o.fee)}</label>`:''}<p class="fineprint">Simulated proof of delivery. No location or identity document is captured.</p><button class="btn primary">Confirm successful delivery</button></form>`);$('#delivery-form').onsubmit=e=>{e.preventDefault();update(()=>{transition(s,id,'deliver');o.deliveryFailed=false},'Delivery complete. Customer tracking updated.')};return}
if(a==='failure'){modal('Record delivery issue',`<form id="failure-form" class="form-fields"><label>Reason<select name="reason"><option>Recipient unavailable</option><option>Address cannot be located</option><option>Restricted-product verification failed</option><option>Vehicle issue</option></select></label><button class="btn primary">Flag for dispatch</button></form>`);$('#failure-form').onsubmit=e=>{e.preventDefault();let reason=new FormData(e.target).get('reason');update(()=>{let o=s.orders.find(x=>x.id===id);o.deliveryFailed=true;o.events.push({at:s.time,text:'Delivery issue: '+reason});log(s,id+' delivery issue: '+reason)},'Dispatch has a new exception.')};return}
if(a==='approve-po'){update(()=>{let p=s.purchaseOrders.find(p=>p.id===id);p.status='approved';log(s,id+' approved')},'Request approved for supplier confirmation.');return}
if(a==='confirm-po'){const p=s.purchaseOrders.find(p=>p.id===id);modal('Supplier confirmation · '+id,`<form id="confirm-po-form" class="form-fields"><p>${p.item} · ${p.ordered} ordered</p><label>Confirmed quantity<input type="number" name="qty" min="${p.received}" max="${p.ordered}" value="${p.confirmed}" required></label><button class="btn primary">Confirm supply</button></form>`);$('#confirm-po-form').onsubmit=e=>{e.preventDefault();update(()=>{p.confirmed=+new FormData(e.target).get('qty');p.status='confirmed';log(s,id+' supplier confirmed '+p.confirmed)},'Supplier response recorded.')};return}
if(a==='receive'){const p=s.purchaseOrders.find(p=>p.id===id);modal('Receive delivery · '+id,`<form id="receive-form" class="form-fields"><p>${p.item} · ${p.ordered-p.received} outstanding</p><label>Accepted quantity<input name="accepted" type="number" min="0" max="${p.ordered-p.received}" value="${Math.min(p.confirmed,p.ordered-p.received)}" required></label><label>Rejected quantity<input name="rejected" type="number" min="0" max="${p.ordered-p.received}" value="0" required></label><p class="fineprint">Rejected units remain outstanding. Receiving does not automatically change menu availability.</p><button class="btn primary">Record receipt</button></form>`);$('#receive-form').onsubmit=e=>{e.preventDefault();let f=new FormData(e.target);update(()=>receive(s,id,+f.get('accepted'),+f.get('rejected')),'Receipt recorded. Outstanding quantity retained.')};return}
if(a==='new-po'){modal('Request replenishment',`<form id="new-po-form" class="form-fields"><label>Supplier<select name="supplier"><option>Fresh Fields Produce</option><option>Valley Meats</option><option>Capital Beverages</option></select></label><label>Item and unit<input name="item" placeholder="e.g. Potatoes · 10kg bags" required maxlength="90"></label><label>Quantity<input name="qty" type="number" value="10" min="1" max="500" required></label><button class="btn primary">Create request</button></form>`);$('#new-po-form').onsubmit=e=>{e.preventDefault();let f=new FormData(e.target);update(()=>{s.purchaseOrders.unshift({id:'PO-'+(201+s.purchaseOrders.length),supplier:f.get('supplier'),branch:s.branch,item:f.get('item'),ordered:+f.get('qty'),confirmed:0,received:0,rejected:0,status:'requested',cost:0});log(s,'New replenishment request created')},'Request ready for approval.')};return}
if(a==='reconcile'){const o=s.orders.find(x=>x.id===id);modal('Review '+id,`<form id="reconcile-form" class="form-fields"><p>Platform total: <b>${money(o.subtotal+o.fee)}</b></p><label>Manual POS reference<input name="ref" value="${esc(o.receipt)}" required maxlength="50" placeholder="Demo receipt reference"></label><label class="checkbox"><input name="reviewed" type="checkbox" ${o.reconciled?'checked':''}> I manually reviewed the reference and amount</label><button class="btn primary">Save review</button></form>`);$('#reconcile-form').onsubmit=e=>{e.preventDefault();let f=new FormData(e.target);update(()=>{o.receipt=f.get('ref');o.reconciled=f.get('reviewed')==='on';log(s,id+' reconciliation reference updated')},'Manual review saved.')};return}
if(a==='help'){modal('Order support',`<p>This is a demonstration support request. No message or call will be sent.</p><form id="help-form" class="form-fields"><label>What needs attention?<select name="issue"><option>My order is delayed</option><option>I need to change my order</option><option>Something is missing</option></select></label><button class="btn primary">Record demo request</button></form>`);$('#help-form').onsubmit=e=>{e.preventDefault();update(()=>log(s,id+' support request: '+new FormData(e.target).get('issue'),'Customer'),'Support request recorded in the activity journal.')};return}
if(a==='scenarios'){modal('Take the demo for a service',`<p>Each scenario starts from a fresh seed so the walkthrough is repeatable.</p><div class="scenario-list">${[['normal','01','A meal from order to doorstep','Start with a food-and-drinks basket.'],['last','02','The last two portions','Test reservation limits at Chitungwiza.'],['busy','03','A busy kitchen','Show longer estimates and a paused branch.'],['driver','04','Ready, but no driver','Resolve a dispatch bottleneck.'],['partial','05','The short delivery','Receive fewer cases than were ordered.'],['payment','06','A declined payment','Keep the basket while payment fails.'],['expiry','07','No branch response','Advance time to release reservations.']].map(([id,n,t,d])=>`<button data-action="scenario" data-id="${id}"><span>${n}</span><div><b>${t}</b><small>${d}</small></div><span>↗</span></button>`).join('')}</div>`,true);bindOverlay();return}
if(a==='scenario'){s=seed();if(['normal','payment','last'].includes(id)){s.cart=[{productId:'p0',name:s.products[0].name,price:850,quantity:1,station:'kitchen',modifier:'Mild',extra:false},{productId:'p23',name:s.products[23].name,price:150,quantity:1,station:'bar',modifier:'',extra:false}];if(id==='last')s.offers['avondale:p0'].allocation=3;route='checkout';}else if(id==='busy'){s.branch='cbd';s.cartBranch='cbd';route='availability'}else if(id==='driver'){s.branch='borrowdale';let o=s.orders.find(o=>o.status==='ready'&&o.mode==='delivery');if(o){o.branch='borrowdale';o.driver=null}route='dispatch'}else if(id==='partial'){s.branch='cbd';let p=s.purchaseOrders[8];p.status='confirmed';p.branch='cbd';p.confirmed=8;route='supply'}else {s.branch='avondale';let o=s.orders.find(o=>o.status==='pending_acceptance');o.branch='avondale';o.expires=3;route='orders'}save();close();location.hash=route;render();notify('Scenario loaded. Use the workspaces to continue.');return}
}catch(e){notify(e.message)}}
let revealObserver,filmObserver;
function bind(){clearTimeout(logoClickTimer);const logo=$('.brand');if(logo){logo.onclick=e=>{clearTimeout(logoClickTimer);if(e.detail===0){toggleNavigation();return;}logoClickTimer=setTimeout(toggleNavigation,350)};logo.ondblclick=e=>{e.preventDefault();clearTimeout(logoClickTimer);window.scrollTo({top:0,behavior:window.matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'})};logo.onkeydown=e=>{if(e.key==='Home'){e.preventDefault();window.scrollTo({top:0,behavior:window.matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'})}};}if(filmObserver)filmObserver.disconnect();const film=$('.hero-film');if(film){const reduced=window.matchMedia('(prefers-reduced-motion: reduce)').matches;const saveData=navigator.connection?.saveData;if(!reduced&&!saveData&&!atmospherePaused){const src=film.querySelector('source');src.src=src.dataset.src;film.load();film.play().then(()=>film.classList.add('playing')).catch(()=>{});film.onplaying=()=>film.classList.add('playing');film.onerror=()=>film.classList.remove('playing');filmObserver=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting&&!$('.signature-hero')?.classList.contains('motion-paused'))film.play().catch(()=>{});else film.pause()}),{threshold:.05});filmObserver.observe(film)}else{const h=$('.signature-hero');h.classList.add('motion-paused');const control=h.querySelector('.motion-control');control.textContent='▷ Play atmosphere';control.setAttribute('aria-pressed','true')}}if(revealObserver)revealObserver.disconnect();if('IntersectionObserver' in window){revealObserver=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add('revealed');revealObserver.unobserve(e.target)}}),{threshold:.12});document.querySelectorAll('.reveal').forEach(el=>revealObserver.observe(el))}else document.querySelectorAll('.reveal').forEach(el=>el.classList.add('revealed'));const hero=$('.signature-hero');if(hero&&!window.matchMedia('(prefers-reduced-motion: reduce)').matches){hero.onpointermove=e=>{if(e.pointerType!=='mouse')return;const r=hero.getBoundingClientRect();hero.style.setProperty('--pointer-x',((e.clientX-r.left)/r.width-.5)*12+'px');hero.style.setProperty('--pointer-y',((e.clientY-r.top)/r.height-.5)*8+'px')};hero.onpointerleave=()=>{hero.style.setProperty('--pointer-x','0px');hero.style.setProperty('--pointer-y','0px')}};document.querySelectorAll('#app [data-action]').forEach(el=>el.onclick=()=>act(el));document.querySelectorAll('[data-branch]').forEach(el=>el.onclick=()=>{s.branch=el.dataset.branch;save()});document.querySelectorAll('[data-filter]').forEach(el=>el.onclick=()=>{orderFilter=el.dataset.filter;render()});document.querySelectorAll('.category-tabs [data-category]').forEach(el=>el.onclick=()=>{category=el.dataset.category;document.querySelectorAll('.category-tabs [data-category]').forEach(x=>x.classList.toggle('active',x.dataset.category===category));refreshCatalogue()});if($('#role'))$('#role').onchange=e=>{role=e.target.value;const r={owner:'overview',branch:'orders',dispatch:'dispatch',driver:'driver',supplier:'suppliers',customer:'menu'}[role];go(r)};if($('#branch'))$('#branch').onchange=e=>{s.branch=e.target.value;save();render()};if($('#driver-select'))$('#driver-select').onchange=e=>{s.driver=e.target.value;save();render()};if($('#shop-branch'))$('#shop-branch').onchange=e=>changeBranch(e.target.value);for(const id of ['search','menu-search'])if($('#'+id))$('#'+id).oninput=e=>{search=e.target.value;const pos=e.target.selectionStart;if(route==='order'){refreshCatalogue()}else{$('#content').innerHTML=views[route]();bind();const el=$('#'+id);el.focus();el.setSelectionRange(pos,pos)}};
if($('#checkout-form'))$('#checkout-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);if(f.get('zone')==='outside'){notify('This address is outside the demo delivery areas. Choose collection or another area.');return}try{submit(s,{key:'checkout-'+s.orders.length+'-'+s.time,customer:f.get('customer'),branch:s.cartBranch,lines:structuredClone(s.cart),mode:s.fulfilment,zone:f.get('zone')||bn(s.cartBranch),address:f.get('address')||'Branch collection',payment:f.get('payment')});save();go('tracking');notify('Order placed. Open the branch order book to accept it.')}catch(e){notify(e.message)}};
if($('#settings-form'))$('#settings-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);update(()=>{branch().foodOpen=f.get('food')==='true';branch().barOpen=f.get('bar')==='true';branch().prep=+f.get('prep');s.settings.acceptance=+f.get('acceptance');log(s,bn(s.branch)+' service settings updated')},'Service settings saved.')};
if($('#enquiry-form'))$('#enquiry-form').onsubmit=e=>{e.preventDefault();let f=new FormData(e.target);update(()=>{s.enquiries.unshift(Object.fromEntries(f));log(s,'New event enquiry recorded','Guest')},'Demo enquiry saved. No real message was sent.')};}
window.addEventListener('hashchange',()=>{route=location.hash.slice(1)||'menu';search='';close();render();window.scrollTo(0,0)});window.addEventListener('storage',e=>{if(e.key==='ember-demo-v1'){try{s=updateBranchLabels(JSON.parse(e.newValue));if(['menu','order'].includes(route))refreshCustomer();else if(!$('#overlay').innerHTML&&!['checkout','services','settings'].includes(route))render()}catch{}}});setInterval(()=>{if(!s.paused){advance(s,1);save();if(['menu','order'].includes(route))refreshCustomer();else if(!$('#overlay').innerHTML&&!['checkout','services','settings'].includes(route))render()}},15000);render();
